            .Request               = _obj.rx_dma.request,
            .BlkHWRequest          = DMA_BREQ_SINGLE_BURST,
            .Direction             = DMA_PERIPH_TO_MEMORY,
            .SrcInc                = DMA_SINC_FIXED,
            .DestInc               = DMA_DINC_INCREMENTED,
            .SrcDataWidth          = DMA_SRC_DATAWIDTH_BYTE,
